import java.util.*;

class Solution {
    private List<List<Integer>> res = new ArrayList<>();
    private List<Integer> cur = new ArrayList<>();

    public List<List<Integer>> subsets(int[] items) {
        go(items, 0);
        return res;
    }

    private void go(int[] items, int i) {
        if (i == items.length) {             // every element decided
            res.add(new ArrayList<>(cur));   // save a copy
            return;
        }
        go(items, i + 1);                    // exclude items[i]
        cur.add(items[i]);                   // include items[i]
        go(items, i + 1);
        cur.remove(cur.size() - 1);          // undo for the next branch
    }
}

