class Solution:
    def subsets(self, items: List[int]) -> List[List[int]]:
        out = []
        def go(i, cur):
            if i == len(items): out.append(cur[:]); return
            go(i + 1, cur)
            cur.append(items[i]); go(i + 1, cur); cur.pop()
        go(0, [])
        return out
